      {{ include('ui/box/box.html.twig', {'p': {'Class': ui_s(ui_cnv(['w-full min-w-0', (ui_t(ui_eq(v_mediaSide, 'start')) ? 'md:order-first' : (ui_t(ui_eq(v_mediaSide, 'alternate')) ? 'md:group-even:order-first' : ''))]))}, 'children': c_4}, with_context = false) }}
